mapper.select:
SELECT id, owner_account_id, title, input_revision, same_project, same_cost, created_at, updated_at
FROM combination_review
WHERE id = #{reviewId} AND owner_account_id = #{ownerAccountId}

SELECT c.id, c.title, c.input_revision, c.created_at, c.updated_at,
       r.id AS latest_run_id, r.input_revision AS latest_run_input_revision, r.status AS latest_run_status,
       r.failure_code AS latest_run_failure_code, r.started_at AS latest_run_started_at, r.finished_at AS latest_run_finished_at
FROM combination_review c
LEFT JOIN combination_review_run r ON r.id = (
    SELECT MAX(x.id) FROM combination_review_run x WHERE x.review_id = c.id
)
WHERE c.owner_account_id = #{ownerAccountId}

    AND c.id < #{beforeId}

ORDER BY c.id DESC
LIMIT #{limit}

mapper.update:
UPDATE combination_review
SET title = #{title},

    same_project = #{sameProject}, same_cost = #{sameCost},

    input_revision = input_revision + 1, updated_at = #{updatedAt}
WHERE id = #{reviewId} AND owner_account_id = #{ownerAccountId} AND input_revision = #{expectedRevision}

mapper.delete:
DELETE p FROM combination_review_program p
INNER JOIN combination_review r ON r.id = p.review_id
WHERE r.id = #{reviewId} AND r.owner_account_id = #{ownerAccountId}
